const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
const point=(angle,r)=>({x:320+r*Math.sin(angle),y:320-r*Math.cos(angle)});
for(let i=0;i<60;i++){const a=i*Math.PI/30,p=point(a,i%5?246:240),q=point(a,255),line=document.createElementNS(NS,'line');for(const[k,v]of Object.entries({x1:p.x,y1:p.y,x2:q.x,y2:q.y,class:`tick ${i%5?'':'major'}`}))line.setAttribute(k,v);$('ticks').append(line);if(i%5===0){const t=document.createElementNS(NS,'text'),p=point(a,286);t.setAttribute('x',p.x);t.setAttribute('y',p.y);t.setAttribute('text-anchor','middle');t.setAttribute('dominant-baseline','central');t.textContent=i;$('numbers').append(t)}}
const isLocked=()=>window.isScreenLocked?.()===true;
let duration=25*60,remaining=duration,running=false,end=0,completed=false,audioCtx,wakeLock,dragging=false,finishAcknowledged=false;
const viewOptions=['auto-lock','keep-screen','show-digits','show-dial-numbers'];
const colors=[['#f46e58','#f47760','#f9dfd6'],['#6e8e75','#86a68b','#e0ebdf'],['#648da7','#83a7bc','#deebf3'],['#a17cb2','#b599c2','#eee0f2']];let colorIndex=0;
function persist(){try{localStorage.setItem('focus-dial',JSON.stringify({duration,remaining,running,end,completed,task:$('task').value,sound:$('sound').checked,awake:$('awake').checked,visual:$('visual').checked,dark:document.body.classList.contains('dark'),colorIndex,view:Object.fromEntries(viewOptions.map(id=>[id,$(id).checked]))}))}catch{}}
function applyColor(){const c=colors[colorIndex];document.documentElement.style.setProperty('--accent',c[0]);document.documentElement.style.setProperty('--sector',c[1]);document.documentElement.style.setProperty('--soft',document.body.classList.contains('dark')?`${c[0]}30`:c[2]);}
function render(){const seconds=Math.ceil(remaining);$('time').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;document.title=running?`${$('time').textContent} · 집중 다이얼`:'집중 다이얼';const fraction=Math.min(1,remaining/3600),a=fraction*2*Math.PI,p=point(a,258);$('sector').setAttribute('d',fraction>=.999999?'M320 62 A258 258 0 1 1 319.999 62 L320 320 Z':fraction>0?`M320 320 L320 62 A258 258 0 ${fraction>.5?1:0} 1 ${p.x} ${p.y} Z`:'');const h=point(a,238);$('hand').setAttribute('x2',h.x);$('hand').setAttribute('y2',h.y);$('dial').setAttribute('aria-valuenow',Math.round(remaining/60));$('dial').setAttribute('aria-valuetext',`${Math.floor(seconds/60)}분 ${seconds%60}초 남음`);$('start-label').textContent=running?'잠시 멈춤':completed?'다시 시작':remaining<duration?'이어서 집중':'집중 시작';$('play-icon').textContent=running?'Ⅱ':'▶';$('status').textContent=running?'집중하고 있어요':completed?'잘했어요, 잠깐 쉬어가요':remaining<duration?'잠시 쉬어가는 중':'나만의 집중 시간';$('remaining').textContent=running?'지금 하고 있는 일에만 집중해요':completed?'오늘의 작은 집중을 완성했어요':remaining<duration?'준비되면 이어서 시작하세요':`${duration/60}분의 여유, 지금 시작해요`;$('dial').setAttribute('aria-disabled',running);document.body.classList.toggle('running',running);document.body.classList.toggle('finished',completed&&$('visual').checked&&!finishAcknowledged);document.body.classList.toggle('hide-digits',running&&!$('show-digits').checked);document.body.classList.toggle('hide-dial-numbers',running&&!$('show-dial-numbers').checked);document.querySelectorAll('[data-min]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.min)*60===duration));window.dispatchEvent(new CustomEvent('timerstate',{detail:{running,completed}}));}
function initAudio(){try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume().catch(()=>{})}catch{}}
function chime(){initAudio();if(!audioCtx)return;[523.25,659.25,783.99].forEach((freq,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain(),t=audioCtx.currentTime+i*.22;o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.18,t+.02);g.gain.exponentialRampToValueAtTime(.001,t+.8);o.connect(g);g.connect(audioCtx.destination);o.start(t);o.stop(t+.85)})}
async function syncWake(){if(!running||!$('awake').checked||document.hidden){if(wakeLock){await wakeLock.release().catch(()=>{});wakeLock=null}return}if(!('wakeLock'in navigator)){ $('notice').textContent='이 브라우저에서는 화면 자동 꺼짐 설정을 직접 조절해 주세요.';return}try{if(!wakeLock)wakeLock=await navigator.wakeLock.request('screen');wakeLock.addEventListener('release',()=>{wakeLock=null},{once:true})}catch{$('notice').textContent='화면 켜짐 유지가 제한되어 있어요. 기기 설정을 확인해 주세요.'}}
function tick(){if(!running)return;remaining=Math.max(0,(end-Date.now())/1000);if(remaining<=0){running=false;completed=true;if($('sound').checked)chime();$('notice').textContent='집중 시간이 끝났어요. 수고했어요!';persist();syncWake()}render()}
function setMinutes(minutes){if(isLocked())return;if(running){$('notice').textContent='시간을 바꾸려면 먼저 잠시 멈춰 주세요.';return}duration=Math.max(1,Math.min(60,Math.round(minutes)))*60;remaining=duration;completed=false;finishAcknowledged=false;$('notice').textContent='';render();persist()}
$('start').onclick=()=>{if(isLocked())return;initAudio();if(running){remaining=Math.max(0,(end-Date.now())/1000);running=false}else{if(completed||remaining<=0){remaining=duration;completed=false}end=Date.now()+remaining*1000;running=true}$('notice').textContent='';render();persist();syncWake()};
$('reset').onclick=()=>{if(isLocked())return;running=false;remaining=duration;completed=false;finishAcknowledged=false;$('notice').textContent='처음 설정한 시간으로 돌아왔어요.';render();persist();syncWake()};
document.querySelectorAll('[data-min]').forEach(b=>b.onclick=()=>setMinutes(Number(b.dataset.min)));
function pointerMinutes(e){const rect=$('dial').getBoundingClientRect();let a=Math.atan2(e.clientX-rect.left-rect.width/2,-(e.clientY-rect.top-rect.height/2));if(a<0)a+=2*Math.PI;return Math.max(1,Math.round(a/(2*Math.PI)*60))}
$('dial').addEventListener('pointerdown',e=>{if(isLocked())return;if(running){$('notice').textContent='시간을 바꾸려면 먼저 잠시 멈춰 주세요.';return}dragging=true;$('dial').setPointerCapture(e.pointerId);setMinutes(pointerMinutes(e))});$('dial').addEventListener('pointermove',e=>{if(dragging)setMinutes(pointerMinutes(e))});for(const ev of['pointerup','pointercancel'])$('dial').addEventListener(ev,()=>dragging=false);
$('dial').addEventListener('keydown',e=>{if(isLocked())return;const steps={ArrowUp:1,ArrowRight:1,ArrowDown:-1,ArrowLeft:-1};if(e.key in steps){e.preventDefault();setMinutes(duration/60+steps[e.key])}if(e.key==='Home'){e.preventDefault();setMinutes(1)}if(e.key==='End'){e.preventDefault();setMinutes(60)}});
$('theme').onclick=()=>{document.body.classList.toggle('dark');applyColor();persist()};$('color').onclick=()=>{colorIndex=(colorIndex+1)%colors.length;applyColor();persist()};$('settings').onclick=()=>$('settings-dialog').showModal();$('test-sound').onclick=chime;
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{$('notice').textContent='이 환경에서는 전체 화면을 사용할 수 없어요.'}};
for(const id of['sound','awake','visual',...viewOptions])$(id).onchange=()=>{if(id==='visual')finishAcknowledged=false;persist();render();syncWake()};$('task').oninput=persist;
document.addEventListener('visibilitychange',()=>{tick();syncWake()});window.addEventListener('pagehide',persist);
try{const s=JSON.parse(localStorage.getItem('focus-dial'));if(s&&Number.isFinite(s.duration)&&s.duration>=60&&s.duration<=3600){duration=s.duration;remaining=Math.max(0,Math.min(duration,Number(s.remaining)||0));running=!!s.running&&Number.isFinite(s.end);end=s.end;completed=!!s.completed;$('task').value=s.task||'';for(const id of['sound','awake','visual'])if(typeof s[id]==='boolean')$(id).checked=s[id];for(const id of viewOptions)if(typeof s.view?.[id]==='boolean')$(id).checked=s.view[id];document.body.classList.toggle('dark',!!s.dark);colorIndex=Number.isInteger(s.colorIndex)?Math.abs(s.colorIndex)%colors.length:0}}catch{}
document.addEventListener('pointerdown',()=>{if(completed&&!finishAcknowledged){finishAcknowledged=true;render()}},{capture:true});
function clock(){ $('clock').textContent=new Intl.DateTimeFormat('ko-KR',{month:'long',day:'numeric',weekday:'short',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())}applyColor();tick();render();clock();syncWake();setInterval(tick,200);setInterval(clock,10000);
if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
